def block(name='A.one', header=None, axioms=None):
    header = name + ' : True' if header is None else header
    axioms = "'" + name + "' depends on axioms: []" if axioms is None else axioms
    return f'AUDIT_BEGIN {name}\n{header}\n{axioms}\nAUDIT_END {name}\n'


class FormalAuditParserTests(unittest.TestCase):
    def rejected(self, text, targets=None):
        with self.assertRaises(gate.GateError):
            gate.parse_audit(text, ['A.one'] if targets is None else targets)

    def test_exact_preserved_82_transcript_and_raw_text(self):
        self.assertEqual(hashlib.sha256(TRANSCRIPT.encode()).hexdigest(), TRANSCRIPT_SHA256)
        result = gate.parse_audit(TRANSCRIPT, TRANSCRIPT_TARGETS)
        self.assertEqual(set(result), set(TRANSCRIPT_TARGETS))
        self.assertEqual(len(result), 82)
        for name, value in result.items():
            original = TRANSCRIPT.split('AUDIT_BEGIN ' + name + '\n', 1)[1].split('AUDIT_END ' + name + '\n', 1)[0]
            self.assertEqual(value['type_and_axiom_text'], original.strip())

    def test_supported_header_forms(self):
        headers = [
            'A.one : True',
            'A.one (s : ' + json.dumps('quoted "bracket)"') + ' = ' + json.dumps('quoted "bracket)"') + ') : True',
            'A.one.{u_1, u_2} : True',
            'A.one (x : Nat) : x = x',
            'A.one {x : Nat} : x = x',
            'A.one [inst : Inhabited Nat] : True',
            'A.one ⦃x : Nat⦄ : x = x',
            'A.one {α : Type u} (f : (x : α) → {y : α // y = x}) [Inhabited α] : True',
            'A.one.{u} {α : Type u}\n  (f : (x : α) → {y : α // y = x})\n  ⦃x : α⦄ :\n  x = x',
            'A.one (s : "(colon: [bracket])" = "(colon: [bracket])") : True',
        ]
        for header in headers:
            with self.subTest(header=header):
                self.assertEqual(gate.parse_audit(block(header=header), ['A.one'])['A.one']['axioms'], [])

    def test_axiom_footprints(self):
        for record, expected in [
            ("'A.one' does not depend on any axioms", []),
            ("'A.one' depends on axioms: [propext,\n Classical.choice, Quot.sound]", ['Classical.choice', 'Quot.sound', 'propext']),
        ]:
            self.assertEqual(gate.parse_audit(block(axioms=record), ['A.one'])['A.one']['axioms'], expected)

    def test_target_and_marker_completeness(self):
        good = block()
        for text, requested in [
            (good, []), (good, ['A.one', 'A.one']), (good, ['A.one', 'A.two']),
            (good + block('A.two'), ['A.one']), (good * 2, ['A.one']),
            (good.replace('AUDIT_END A.one', 'AUDIT_END A.two'), ['A.one']),
            (good.replace('AUDIT_END A.one', ''), ['A.one']),
            ('spoof AUDIT_BEGIN A.two\n' + good, ['A.one']),
            (good + 'AUDIT_END A.two\n', ['A.one']),
        ]:
            with self.subTest(text=text, requested=requested): self.rejected(text, requested)

    def test_exact_identity_and_one_type(self):
        for header in ['', 'Other.one : True', 'A.oneSuffix : True', 'PrefixA.one : True',
                       'A.one', 'A.one (x : Nat)', 'A.one :', 'A.one :   ',
                       'A.one : True\nA.one : True', 'A.one : True\nOther.one : True', 'A.one : True\n  A.one : True']:
            with self.subTest(header=header): self.rejected(block(header=header))

    def test_balanced_binders_and_universes(self):
        for header in ['A.one (x : Nat : True', 'A.one {x : Nat) : True',
                       'A.one [Inhabited Nat : True', 'A.one ⦃x : Nat} : True',
                       'A.one.{u : True', 'A.one.{} : True', 'A.one.{u,,v} : True',
                       'A.one.{u}Suffix : True', 'A.one (x : (Nat]) : True',
                       'A.one (s : "unterminated) : True']:
            with self.subTest(header=header): self.rejected(block(header=header))

    def test_exact_single_axiom_record(self):
        good = "'A.one' depends on axioms: []"
        for record in ['', "'Other.one' depends on axioms: []", "'PrefixA.one' depends on axioms: []",
                       "'A.oneSuffix' depends on axioms: []", good + '\n' + good,
                       good + "\n'A.one' does not depend on any axioms",
                       good + "\n'Other.one' depends on axioms: []",
                       "'Other.one' depends on axioms: []\n" + good]:
            with self.subTest(record=record): self.rejected(block(axioms=record))

    def test_unapproved_axiom_and_sorry_anywhere(self):
        for axiom in ['sorryAx', 'Custom.axiom', 'Lean.ofReduceBool']:
            self.rejected(block(axioms="'A.one' depends on axioms: [" + axiom + ']'))
        self.rejected('sorryAx\n' + block())
        self.rejected(block() + 'sorryAx\n')

    def test_subset_cannot_satisfy_complete_contract(self):
        contract = json.loads((ROOT / 'source/formal_targets.json').read_text())
        required = [n for row in contract['modules'] for n in row['targets']]
        self.assertEqual(len(required), 145)
        self.rejected(TRANSCRIPT, required)
        self.rejected(TRANSCRIPT, required + ['OrthemologyConvergence.upstreamGirard'])

    def test_enclosing_version_artifact_and_source_guards(self):
        # These are policy negatives, never a real Lean success fixture.
        with self.assertRaises(gate.GateError):
            gate.enforce_version('4.19.0', 'Lean (version 4.32.2, diagnostic)\n')
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory); artifact = root / 'A.olean'
            with self.assertRaises(gate.GateError): gate.check_artifact(artifact)
            artifact.write_bytes(b'')
            with self.assertRaises(gate.GateError): gate.check_artifact(artifact)
            (root / 'MANIFEST.json').write_text(json.dumps({'files': [{'path': 'A.olean', 'bytes': 9, 'sha256': '0' * 64}]}))
            with self.assertRaises(gate.GateError): gate.verify_manifest(root)
            result = gate.run_bounded([sys.executable, '-c', 'print(' + repr(block()) + ');raise SystemExit(1)'], root, timeout=3)
            self.assertEqual(result['exit_code'], 1)
            self.assertFalse(result['ok'])


if __name__ == '__main__': unittest.main()
